async (api, target) => {
  const fl = Math.floor;
  const S = () => api.self();
  const key = (x, y, z) => x + ',' + y + ',' + z;
  const isAir = (n) => !n || n === 'air' || n === 'cave_air';
  const me = S().pos;
  const sc = await api.scan({ match: target.name, radius: 24 });
  const ls = await api.scan({ match: "*_log", radius: 24 });
  const tgtLeaves = target.name.endsWith('_leaves');
  const wood0 = target.name.replace(/_(log|leaves)$/, '');
  const nearTarget = (x, y, z) => {
    for (let dy = -3; dy <= 10; dy++) for (let dx = -3; dx <= 3; dx++) for (let dz = -3; dz <= 3; dz++)
      if (api.blockAt(x + dx, y + dy, z + dz) === target.name) return true;
    return false;
  };
  let tx, tz, base, wood;
  const cands = [];
  if (ls && ls.total) for (const c of ls.clusters) for (const p of c.positions) {
    const n = api.blockAt(p[0], p[1], p[2]);
    if (!n) continue;
    if (!tgtLeaves && n !== target.name) continue;
    if (tgtLeaves && n.replace(/_log$/, '') !== wood0) continue;
    cands.push(p);
  }
  cands.sort((a, b) => Math.hypot(a[0] - me[0], a[2] - me[2]) - Math.hypot(b[0] - me[0], b[2] - me[2]));
  let best = null;
  for (const p of cands.slice(0, 12)) { if (!tgtLeaves || nearTarget(p[0], p[1], p[2])) { best = p; break; } await api.wait(1); }
  if (!best && cands.length) best = cands[0];
  if (best) {
    tx = best[0]; tz = best[2];
    wood = api.blockAt(best[0], best[1], best[2]).replace(/_log$/, '');
    let y = best[1];
    while (api.blockAt(tx, y - 1, tz) === wood + '_log') y--;
    base = y;
  } else {
    if (!sc || !sc.total) return "none_found";
    const cl = sc.clusters.slice().sort((a, b) => a.dist - b.dist)[0];
    tx = cl.nearest[0]; tz = cl.nearest[2]; base = cl.nearest[1]; wood = wood0;
  }
  let gy = base;
  for (let i = 0; i < 30; i++) { const n = api.blockAt(tx, gy - 1, tz); if (!isAir(n) && !n.endsWith('_leaves') && !n.endsWith('_log')) break; gy--; }
  const placed = new Set();
  const skip = new Set();
  const isTree = (x, y, z) => {
    if (placed.has(key(x, y, z))) return false;
    const n = api.blockAt(x, y, z); if (!n) return false;
    return n === wood + '_log' || n === wood + '_leaves' || n === target.name;
  };
  const remaining = () => {
    const out = [];
    for (let y = gy - 1; y <= gy + 24; y++) for (let dx = -3; dx <= 3; dx++) for (let dz = -3; dz <= 3; dz++) {
      const x = tx + dx, z = tz + dz;
      if (isTree(x, y, z) && !skip.has(key(x, y, z))) out.push([x, y, z]);
    }
    return out;
  };
  const feet = () => { const p = S().pos; return [fl(p[0]), fl(p[1] + 0.05), fl(p[2])]; };
  const inReach = (b) => {
    const p = S().pos;
    return Math.hypot(b[0] + 0.5 - p[0], b[1] + 0.5 - (p[1] + 1.62), b[2] + 0.5 - p[2]) <= 4.4;
  };
  const hasAxe = () => Object.keys(api.inventory()).find(n => n.endsWith('_axe'));
  const digOne = async (b) => {
    const f = feet();
    if (b[0] === f[0] && b[2] === f[2] && b[1] < f[1]) return false; // never dig own support
    try {
      const n = api.blockAt(b[0], b[1], b[2]);
      const ax = hasAxe();
      if (n && n.endsWith('_log') && ax) { const h = api.held(); if (!h || h.name !== ax) await api.equip(ax); }
      await api.dig(b[0], b[1], b[2]);
      return true;
    } catch (e) { skip.add(key(b[0], b[1], b[2])); return false; }
  };
  const digReach = async () => {
    for (let pass = 0; pass < 3; pass++) {
      const f = feet();
      const list = remaining().filter(b => inReach(b) && !(b[0] === f[0] && b[2] === f[2] && b[1] < f[1])).sort((a, b) => b[1] - a[1]);
      if (!list.length) return;
      for (const b of list) { if (isTree(b[0], b[1], b[2]) && inReach(b)) await digOne(b); }
    }
  };
  const pickBlock = () => {
    const inv = api.inventory();
    for (const n of ['dirt', 'cobblestone', 'cobbled_deepslate', 'netherrack', 'stone']) if (inv[n]) return n;
    return Object.keys(inv).find(n => n.endsWith('_planks')) || Object.keys(inv).find(n => n.endsWith('_log'));
  };
  const climb = async () => {
    const [x, y, z] = feet();
    if (!isAir(api.blockAt(x, y + 2, z))) {
      if (isTree(x, y + 2, z)) { if (!(await digOne([x, y + 2, z]))) return false; }
      else return false;
    }
    for (let attempt = 0; attempt < 4; attempt++) {
      const blk = pickBlock(); if (!blk) return false;
      try { await api.equip(blk); } catch (e) { return false; }
      await api.look(x + 0.5, y - 0.5, z + 0.5);
      await api.control('jump', true);
      let ok = false;
      for (let t = 0; t < 16 && !ok; t++) {
        await api.wait(1);
        if (S().pos[1] > y + 1.02) { try { await api.place(x, y, z); ok = true; } catch (e) {} }
      }
      await api.control('jump', false);
      for (let t = 0; t < 20; t++) { await api.wait(1); if (S().on_ground) break; }
      if (!isAir(api.blockAt(x, y, z))) { placed.add(key(x, y, z)); return true; }
    }
    return false;
  };
  const descend = async (groundY) => {
    for (let i = 0; i < 60; i++) {
      const [x, y, z] = feet();
      if (y <= groundY) return true;
      await digReach();
      if (isAir(api.blockAt(x, y - 1, z))) { await api.wait(5); continue; }
      if (y - 2 >= groundY - 1 && isAir(api.blockAt(x, y - 2, z))) {
        const blk = pickBlock(); if (!blk) return false;
        try { await api.equip(blk); await api.place(x, y - 2, z); placed.add(key(x, y - 2, z)); }
        catch (e) { return false; }
        continue;
      }
      const k = key(x, y - 1, z);
      const n = api.blockAt(x, y - 1, z);
      if (!(placed.has(k) || isTree(x, y - 1, z) || n === wood + '_log')) return false;
      try {
        const ax = hasAxe();
        if (n && n.endsWith('_log') && ax) await api.equip(ax);
        await api.dig(x, y - 1, z);
      } catch (e) { return false; }
      placed.delete(k);
      for (let t = 0; t < 30; t++) { await api.wait(1); if (S().on_ground && S().pos[1] < y - 0.5) break; }
    }
    return false;
  };
  const groundY = gy;
  if (feet()[1] <= gy + 1) {
    try { await api.goto(tx, gy, tz, 2); } catch (e) {}
    await digReach();
    for (const dy of [0, 1]) if (isTree(tx, gy + dy, tz)) await digOne([tx, gy + dy, tz]);
    try { await api.goto(tx, gy, tz, 0); } catch (e) {}
    const f = feet();
    if (f[0] !== tx || f[2] !== tz) {
      await api.look(tx + 0.5, S().pos[1] + 1.6, tz + 0.5);
      await api.control('forward', true); await api.wait(5); await api.control('forward', false); await api.wait(5);
    }
  }
  let down = true;
  for (let round = 0; round < 3; round++) {
    for (let i = 0; i < 26; i++) {
      await digReach();
      const rem = remaining();
      if (!rem.length) break;
      const fy = feet()[1];
      if (!rem.some(b => b[1] >= fy)) break;
      if (fy >= gy + 24) break;
      if (!(await climb())) break;
    }
    down = await descend(groundY);
    if (!down) break;
    await digReach();
    if (!remaining().length) break;
  }
  if (!down || placed.size) return "stuck";
  return remaining().length ? "stuck" : "done";
}
